import React, { useState } from 'react'

export const ReportsListScreen = () => {
  const [selectedReport, setSelectedReport] = useState<string | null>(null)
  const [reportData, setReportData] = useState<any[]>([])

  const reports = [
    { id: 'inventory_value', name: 'Inventory Valuation Report', description: 'Current inventory value by location and category' },
    { id: 'po_history', name: 'Purchase Order History', description: 'Historical purchase orders with receiving status' },
    { id: 'vendor_performance', name: 'Vendor Performance Report', description: 'Vendor delivery performance and quality metrics' },
    { id: 'stock_turnover', name: 'Stock Turnover Report', description: 'Inventory turnover rates and aging analysis' },
    { id: 'low_stock', name: 'Low Stock Alert Report', description: 'Items below reorder points requiring attention' },
    { id: 'sales_by_category', name: 'Sales by Category Report', description: 'Sales performance broken down by product category' }
  ]

  const generateReport = async () => {
    if (!selectedReport) return

    // In a real app, this would make an API call to generate the report
    // For demo purposes, we'll simulate with mock data
    setReportData([
      { 
        metric: 'Sample Data 1', 
        value: 'Value 1', 
        description: 'This is sample report data'
      },
      { 
        metric: 'Sample Data 2', 
        value: 'Value 2', 
        description: 'This is sample report data'
      }
    ])
  }

  return (
    <div className="screen-container">
      <div className="screen-header">
        <h1 className="screen-title">Reports</h1>
      </div>

      <div className="card">
        <div className="card-header">
          <h2 className="card-title">Select Report</h2>
        </div>
        <div className="card-body">
          <div className="list-group">
            {reports.map((report) => (
              <div 
                key={report.id}
                className={`list-group-item list-group-item-action ${selectedReport === report.id ? 'active' : ''}`}
                onClick={() => setSelectedReport(report.id)}
              >
                <div className="d-flex w-100 justify-content-between">
                  <h5 className="mb-1">{report.name}</h5>
                </div>
                <p className="mb-1">{report.description}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {selectedReport && (
        <>
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">
                {reports.find(r => r.id === selectedReport)?.name} 
                <button 
                  className="btn btn-sm btn-outline-secondary ms-3"
                  onClick={generateReport}
                >
                  Generate Report
                </button>
              </h2>
            </div>
            <div className="card-body">
              {reportData.length > 0 ? (
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Metric</th>
                      <th>Value</th>
                      <th>Description</th>
                    </tr>
                  </thead>
                  <tbody>
                    {reportData.map((row: any, index: number) => (
                      <tr key={index}>
                        <td>{row.metric}</td>
                        <td>{row.value}</td>
                        <td>{row.description}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p className="text-center text-muted py-4">
                  Click "Generate Report" to view results
                </p>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  )
}
